import react from "@vitejs/plugin-react";
import path from "path";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      "@": path.resolve(__dirname, "./src"),
    },
  },
  server: {
    port: 5173,
  },
});

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import "./index.css";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>
);

@tailwind base;
@tailwind components;
@tailwind utilities;

function App() {
  return (
    <div className="min-h-screen bg-background text-foreground">
      <h1 className="text-2xl font-bold p-4">Document Copilot</h1>
    </div>
  );
}

export default App;

class EnvError extends Error {
  constructor(key: string) {
    super(`Missing required env var: ${key}`);
    this.name = "EnvError";
  }
}

function requireEnv(key: string): string {
  const value = import.meta.env[key] as string | undefined;
  if (!value) throw new EnvError(key);
  return value;
}

export const env = {
  apiBaseUrl: requireEnv("VITE_API_BASE_URL"),
  supabaseUrl: requireEnv("VITE_SUPABASE_URL"),
  supabaseAnonKey: requireEnv("VITE_SUPABASE_ANON_KEY"),
};

import { createClient } from "@supabase/supabase-js";
import { env } from "./env";

export const supabase = createClient(env.supabaseUrl, env.supabaseAnonKey);

import { supabase } from "./supabase";

export class ApiError extends Error {
  constructor(
    message: string,
    public status: number,
    public isNetworkError: boolean
  ) {
    super(message);
    this.name = "ApiError";
  }
}

async function getAccessToken(): Promise<string | null> {
  const {
    data: { session },
  } = await supabase.auth.getSession();
  return session?.access_token ?? null;
}

export async function apiFetch<T>(
  url: string,
  options: RequestInit = {}
): Promise<T> {
  const token = await getAccessToken();
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...(options.headers as Record<string, string>),
  };
  if (token) headers["Authorization"] = `Bearer ${token}`;

  let response: Response;
  try {
    response = await fetch(url, { ...options, headers });
  } catch {
    throw new ApiError("Network error", 0, true);
  }

  if (!response.ok) {
    const body = await response.text().catch(() => "");
    throw new ApiError(body || response.statusText, response.status, false);
  }

  return response.json() as Promise<T>;
}

import { env } from "./env";
import { apiFetch } from "./http";

const BASE = env.apiBaseUrl;

export interface ChatThread {
  id: string;
  title: string;
  created_at: string;
}

export interface ChatMessage {
  id: string;
  thread_id: string;
  role: "user" | "assistant";
  content: string;
  created_at: string;
}

export const api = {
  async getThreads(): Promise<ChatThread[]> {
    return apiFetch<ChatThread[]>(`${BASE}/api/threads`);
  },

  async createThread(title?: string): Promise<ChatThread> {
    return apiFetch<ChatThread>(`${BASE}/api/threads`, {
      method: "POST",
      body: JSON.stringify({ title }),
    });
  },

  async getMessages(threadId: string): Promise<ChatMessage[]> {
    return apiFetch<ChatMessage[]>(`${BASE}/api/threads/${threadId}/messages`);
  },
};

