import { Fragment, ReactNode } from "react";

function escapeHtml(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function renderInline(text: string): ReactNode[] {
  const parts: ReactNode[] = [];
  const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\*[^*]+\*)|(\[([^\]]+)\]\(([^)]+)\))/g;
  let last = 0;
  let idx = 0;

  text.replace(re, (match, code, bold, italic, _link, linkText, linkUrl, offset) => {
    if (offset > last) {
      parts.push(<Fragment key={idx++}>{escapeHtml(text.slice(last, offset))}</Fragment>);
    }
    if (code) {
      parts.push(<code key={idx++} className="bg-gray-200 rounded px-1 text-sm font-mono">{escapeHtml(code.slice(1, -1))}</code>);
    } else if (bold) {
      parts.push(<strong key={idx++}>{escapeHtml(bold.slice(2, -2))}</strong>);
    } else if (italic) {
      parts.push(<em key={idx++}>{escapeHtml(italic.slice(1, -1))}</em>);
    } else if (linkText && linkUrl) {
      parts.push(<a key={idx++} href={linkUrl} target="_blank" rel="noopener noreferrer" className="text-blue-600 underline">{escapeHtml(linkText)}</a>);
    }
    last = offset + match.length;
    return match;
  });

  if (last < text.length) {
    parts.push(<Fragment key={idx++}>{escapeHtml(text.slice(last))}</Fragment>);
  }
  return parts;
}

function renderCodeBlock(lang: string | undefined, code: string): ReactNode {
  return (
    <pre className="bg-gray-900 text-gray-100 rounded-lg p-4 my-2 overflow-x-auto text-sm">
      {lang && <div className="text-gray-500 text-xs mb-2 font-mono">{lang}</div>}
      <code className="font-mono">{escapeHtml(code)}</code>
    </pre>
  );
}

export default function Markdown({ content }: { content: string }) {
  const lines = content.split("\n");
  const blocks: ReactNode[] = [];
  let i = 0;
  let key = 0;

  while (i < lines.length) {
    const line = lines[i];

    const fenceMatch = line.match(/^```(\w*)/);
    if (fenceMatch) {
      const lang = fenceMatch[1];
      const codeLines: string[] = [];
      i++;
      while (i < lines.length && !lines[i].startsWith("```")) {
        codeLines.push(lines[i]);
        i++;
      }
      i++;
      blocks.push(<div key={key++} className="animate-slide-up">{renderCodeBlock(lang || undefined, codeLines.join("\n"))}</div>);
      continue;
    }

    if (line.trim() === "") {
      blocks.push(<div key={key++} className="h-2" />);
      i++;
      continue;
    }

    const listMatch = line.match(/^(\s*)[-*]\s+(.*)/);
    if (listMatch) {
      const items: ReactNode[] = [];
      const indent = listMatch[1].length;
      items.push(<li key={0} className="ml-4 list-disc">{renderInline(listMatch[2])}</li>);
      i++;
      while (i < lines.length) {
        const next = lines[i].match(new RegExp(`^ {${indent}}[-*]\\s+(.*)`));
        if (!next) break;
        items.push(<li key={items.length} className="ml-4 list-disc">{renderInline(next[1])}</li>);
        i++;
      }
      blocks.push(<ul key={key++} className="my-1 space-y-0.5">{items}</ul>);
      continue;
    }

    const orderedMatch = line.match(/^(\s*)(\d+)\.\s+(.*)/);
    if (orderedMatch) {
      const items: ReactNode[] = [];
      const indent = orderedMatch[1].length;
      items.push(<li key={0} className="ml-4 list-decimal">{renderInline(orderedMatch[3])}</li>);
      i++;
      while (i < lines.length) {
        const next = lines[i].match(new RegExp(`^ {${indent}}\\d+\\.\\s+(.*)`));
        if (!next) break;
        items.push(<li key={items.length} className="ml-4 list-decimal">{renderInline(next[1])}</li>);
        i++;
      }
      blocks.push(<ol key={key++} className="my-1 space-y-0.5">{items}</ol>);
      continue;
    }

    blocks.push(<p key={key++} className="my-1">{renderInline(line)}</p>);
    i++;
  }

  return <div className="leading-relaxed">{blocks}</div>;
}

import { DefaultChatTransport } from "ai";
import { useChat } from "@ai-sdk/react";
import { useAuth } from "@/hooks/useAuth";
import { env } from "@/lib/env";
import { supabase } from "@/lib/supabase";
import { FormEvent, useEffect, useRef } from "react";
import Markdown from "@/components/Markdown";

function ThinkingDots() {
  return (
    <div className="flex items-center gap-1 px-2 py-2">
      {[0, 1, 2].map((i) => (
        <span key={i} className="thinking-dot w-2 h-2 bg-gray-400 rounded-full" />
      ))}
    </div>
  );
}

function Cursor() {
  return <span className="inline-block w-[2px] h-[1em] bg-gray-600 align-middle ml-0.5 animate-blink" />;
}

export default function ChatPage() {
  const { user, signOut } = useAuth();
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const { messages, status, error, sendMessage, stop } = useChat({
    transport: new DefaultChatTransport({
      api: `${env.apiBaseUrl}/api/chat/stream`,
      headers: async () => {
        const { data } = await supabase.auth.getSession();
        return { Authorization: `Bearer ${data.session?.access_token}` };
      },
    }),
  });

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const input = inputRef.current;
    if (!input || !input.value.trim()) return;
    sendMessage({ text: input.value });
    input.value = "";
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.currentTarget.form?.requestSubmit();
    }
  }

  const isStreaming = status === "streaming" || status === "submitted";
  const lastAssistant = messages.filter((m) => m.role === "assistant").at(-1);
  const assistantStreaming = isStreaming && lastAssistant?.parts?.some(
    (p) => p.type === "text" && "state" in p && p.state === "streaming"
  );

  return (
    <div className="flex flex-col h-screen bg-gray-50">
      <header className="flex items-center justify-between px-5 py-3 bg-white border-b border-gray-200 shrink-0">
        <h1 className="text-lg font-semibold text-gray-900">
          <span className="text-blue-600">Document</span> Copilot
        </h1>
        <div className="flex items-center gap-3">
          <span className="text-sm text-gray-500">{user?.email}</span>
          <button
            onClick={signOut}
            className="text-sm text-gray-500 hover:text-red-600 transition-colors"
          >
            Sign out
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto px-4 py-6">
        <div className="max-w-3xl mx-auto space-y-4">
          {messages.length === 0 && (
            <div className="flex flex-col items-center justify-center mt-32 text-center">
              <div className="w-16 h-16 rounded-2xl bg-blue-100 flex items-center justify-center mb-4">
                <svg className="w-8 h-8 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
              <h2 className="text-xl font-semibold text-gray-700 mb-2">
                Ask about SEC filings
              </h2>
              <p className="text-sm text-gray-400 max-w-md">
                Search across 25 corporate filings from Apple, Microsoft, NVIDIA, Amazon, and Google.
              </p>
            </div>
          )}

          {messages.map((msg) => {
            const isUser = msg.role === "user";
            const text = msg.parts
              ?.filter((p) => p.type === "text")
              .map((p) => ("text" in p ? p.text : ""))
              .join("") ?? msg.content ?? "";

            const isCurrentAssistant = !isUser && msg.id === lastAssistant?.id;

            return (
              <div key={msg.id} className={`flex ${isUser ? "justify-end" : "justify-start"} animate-fade-in`}>
                <div className={`max-w-[75%] ${isUser ? "order-1" : "order-1"}`}>
                  <div
                    className={`rounded-2xl px-4 py-2.5 ${
                      isUser
                        ? "bg-blue-600 text-white"
                        : "bg-white border border-gray-200 text-gray-900 shadow-sm"
                    }`}
                  >
                    {isUser ? (
                      <p className="whitespace-pre-wrap">{text}</p>
                    ) : (
                      <Markdown content={text} />
                    )}
                    {isCurrentAssistant && assistantStreaming && <Cursor />}
                  </div>
                </div>
              </div>
            );
          })}

          {status === "submitted" && !assistantStreaming && (
            <div className="flex justify-start animate-fade-in">
              <div className="bg-white border border-gray-200 rounded-2xl px-4 py-3 shadow-sm">
                <ThinkingDots />
              </div>
            </div>
          )}

          {error && (
            <div className="flex justify-center animate-fade-in">
              <div className="bg-red-50 border border-red-200 text-red-700 text-sm rounded-lg px-4 py-2.5">
                {error.message}
              </div>
            </div>
          )}

          <div ref={bottomRef} />
        </div>
      </main>

      <footer className="border-t border-gray-200 bg-white px-4 py-3 shrink-0">
        <form onSubmit={handleSubmit} className="max-w-3xl mx-auto flex gap-2">
          <div className="flex-1 relative">
            <input
              ref={inputRef}
              name="input"
              type="text"
              placeholder="Ask about SEC filings..."
              disabled={isStreaming}
              onKeyDown={handleKeyDown}
              className="w-full rounded-xl border border-gray-300 bg-gray-50 px-4 py-3 pr-12 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:opacity-50 disabled:cursor-not-allowed transition-shadow"
            />
          </div>
          {isStreaming ? (
            <button
              type="button"
              onClick={stop}
              className="rounded-xl bg-gray-900 px-4 py-3 text-white text-sm font-medium hover:bg-gray-800 transition-colors shrink-0 flex items-center gap-2"
            >
              <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24">
                <rect x="6" y="6" width="12" height="12" rx="1" />
              </svg>
              Stop
            </button>
          ) : (
            <button
              type="submit"
              disabled={status === "submitted"}
              className="rounded-xl bg-blue-600 px-5 py-3 text-white text-sm font-medium hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shrink-0"
            >
              Send
            </button>
          )}
        </form>
      </footer>
    </div>
  );
}

