  const categories = [...new Set(dataPoints.map((dp) => dp.category))].filter(Boolean) as string[];
  const labels = [...new Set(dataPoints.map((dp) => dp.label))];
  return labels.map((label) => {
    const row: Record<string, string | number> = { name: label };
