  });
}

export default function Chart({ data }: { data: ChartData }) {
  const chartData = transformData(data.dataPoints);
  const hasCategories = data.dataPoints.some((dp) => dp.category);
  const categories = [...new Set(data.dataPoints.map((dp) => dp.category).filter(Boolean))] as string[];

  if (data.chartType === "pie") {
